/**
 * Fine jewellery inventory. Prices in LKR (priceFrom: null → "Price on request").
 * Photos are generated by scripts/optimize_images.py into images/opt/<name>-480|960.webp.
 *
 * ⚠ Names describe what is visible in each photo. Confirm the actual gemstone
 *   and metal for every piece and update `gem` / `metal` before launch.
 */
const shot = (name, alt) => ({
  src: `images/opt/${name}-960.webp`,
  srcset: `images/opt/${name}-480.webp 480w, images/opt/${name}-960.webp 960w`,
  width: 960,
  height: 1200,
  alt,
});

